-- Up Migration

-- A consignment's identity and current stage only. Weight, GPS, capture time and chain hash
-- belong to its signed registration step in transactions, so there is one copy of each
-- fact (D2). "Held" is worked out from open alerts, not stored here (D3).
CREATE TABLE consignments (
  id           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  -- The contract's bytes32 id: 16 zero bytes, then the 16 bytes of id. Generated by
  -- PostgreSQL so it can never disagree with id; nobody can write it by hand.
  chain_id     bytea       NOT NULL GENERATED ALWAYS AS (
                 decode(repeat('0', 32) || replace(id::text, '-', ''), 'hex')
               ) STORED,
  qr_code      text        NOT NULL,
  mineral_type text        NOT NULL,
  -- RESTRICT: a miner with consignments cannot be hard-deleted (D9).
  miner_id     uuid        NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
  -- Mirrors the contract's stages. Moving forward only is enforced by the service, under
  -- a row lock, and by the contract.
  stage        text        NOT NULL DEFAULT 'registered',
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),

  -- Also gives a fast lookup when an on-chain event is matched back to its row.
  CONSTRAINT consignments_chain_id_unique UNIQUE (chain_id),
  -- The database's last line of defence against duplicate registration. The service
  -- turns a clash into a duplicate_consignment alert.
  CONSTRAINT consignments_qr_code_unique UNIQUE (qr_code),
  -- QR tag parameters were cut from scope, so this is a tolerant rule: plain codes or
  -- URL-style codes, but no spaces or control characters.
  CONSTRAINT consignments_qr_code_format
    CHECK (qr_code ~ '^[A-Za-z0-9._:/-]+$' AND char_length(qr_code) BETWEEN 4 AND 128),
  -- A fixed list, so FR-09 filters never miss rows because of spelling ('Gold' vs 'gold').
  CONSTRAINT consignments_mineral_valid
    CHECK (mineral_type IN ('gold', 'copper', 'cobalt', 'manganese', 'emerald', 'amethyst')),
  CONSTRAINT consignments_stage_valid
    CHECK (stage IN ('registered', 'in_transit', 'purchased'))
);

-- Serves "my consignments, newest first", and also indexes the foreign key, which
-- PostgreSQL does not do by itself. Column order matters: it helps queries on miner_id
-- alone, but not on created_at alone.
CREATE INDEX consignments_miner_id_created_at_idx ON consignments (miner_id, created_at);

CREATE TRIGGER consignments_set_updated_at
  BEFORE UPDATE ON consignments
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Down Migration

DROP TABLE consignments;
